export type RegistryModule = {
  name: string;
  hasModuleTs: boolean;
  hasEnv: boolean;
  hasAuth: boolean;
  hasAuthClient: boolean;
  locales: string[];
};

export const GENERATED_HEADER =
  "// generated by wa — nie edytuj. Uruchom: npx wa generate";

const MESSAGE_LOCALES = ["pl", "en"] as const;

function identifier(name: string, suffix: string): string {
  const camel = name.replace(/[-_.]+(.)/g, (_, char: string) =>
    char.toUpperCase(),
  );
  return `${camel}${suffix}`;
}

function array(items: string[]): string {
  return items.length === 0 ? "[]" : `[${items.join(", ")}]`;
}

function typedArray(name: string, items: string[]): string {
  return items.length === 0
    ? `export const ${name}: never[] = [];`
    : `export const ${name} = ${array(items)};`;
}

export function renderRegistry(modules: RegistryModule[]): {
  server: string;
  client: string;
} {
  const withModule = modules.filter((m) => m.hasModuleTs);
  const withEnv = modules.filter((m) => m.hasEnv);
  const withAuth = modules.filter((m) => m.hasAuth);
  const withAuthClient = modules.filter((m) => m.hasAuthClient);

  const server = [
    GENERATED_HEADER,
    ...withModule.map(
      (m) =>
        `import ${identifier(m.name, "Module")} from "@/features/${m.name}/module";`,
    ),
    ...withEnv.map(
      (m) =>
        `import { envSchema as ${identifier(m.name, "EnvSchema")} } from "@/features/${m.name}/env";`,
    ),
    ...withAuth.map(
      (m) =>
        `import { authPlugin as ${identifier(m.name, "AuthPlugin")} } from "@/features/${m.name}/auth";`,
    ),
    "",
    typedArray(
      "modules",
      withModule.map((m) => identifier(m.name, "Module")),
    ),
    typedArray(
      "moduleEnvSchemas",
      withEnv.map((m) => identifier(m.name, "EnvSchema")),
    ),
    typedArray(
      "authPlugins",
      withAuth.map((m) => identifier(m.name, "AuthPlugin")),
    ),
    "",
    "export type MessageLoader = { key: string; load: () => Promise<Record<string, unknown>> };",
    "",
    'export const moduleMessages: Record<"pl" | "en", MessageLoader[]> = {',
    ...MESSAGE_LOCALES.flatMap((locale) => {
      const loaders = modules
        .filter((m) => m.locales.includes(locale))
        .map(
          (m) =>
            `{ key: "${m.name}", load: () => import("@/features/${m.name}/i18n/${locale}.json").then((m) => m.default) }`,
        );
      return loaders.length === 0
        ? [`  ${locale}: [],`]
        : [`  ${locale}: [`, ...loaders.map((l) => `    ${l},`), "  ],"];
    }),
    "};",
    "",
  ].join("\n");

  const client = [
    GENERATED_HEADER,
    ...withAuthClient.map(
      (m) =>
        `import { authClientPlugin as ${identifier(m.name, "AuthClientPlugin")} } from "@/features/${m.name}/auth-client";`,
    ),
    ...withModule.map(
      (m) =>
        `import ${identifier(m.name, "Module")} from "@/features/${m.name}/module";`,
    ),
    "",
    typedArray(
      "authClientPlugins",
      withAuthClient.map((m) => identifier(m.name, "AuthClientPlugin")),
    ),
    typedArray(
      "clientModules",
      withModule.map((m) => identifier(m.name, "Module")),
    ),
    "",
  ].join("\n");

  return { server, client };
}
